head.b:skin:
/* =========================================================
   NARA MEDIA - Blogger template (video channel site)
   Each Blogger post = one video card. Paste a YouTube video into
   a post (Insert video) and the thumbnail + player appear.

   EDIT HERE:
   - Colors:  :root below
   - Channel link: search this file for the YouTube address in the
     body and in the script (CHANNEL) and replace it.
   - Hero text, benefits, channel card: see the HOME ONLY block.
   - Menu / footer links / social icons: Layout > edit the widgets.
   ========================================================= */

/* Layout: sticky navy bar, full-bleed storybook hero, four-up benefits, channel card, 4-up video grid, navy footer.
   Palette: --bar navy, --red YouTube red, --sun headline yellow, Google colors only inside the G mark.
   Type: Baloo 2 display (soft, kid-friendly), Nunito body, Caveat for the handwritten thank-you. */
:root{
  --bg:#f5f8fd;--fg:#12203d;--muted:#5a6a86;--card:#ffffff;--line:#e1e8f4;--soft:#eaf1fb;
  --bar:#0e1a33;--bar-fg:#eaf0fc;--red:#e5231b;--red-d:#c41a13;--sun:#ffd23f;--hero:#16364e;
  --blue:#2f7df6;--green:#1fb15a;--purple:#9b3fe0;
  --sh1:0 1px 2px rgba(14,26,51,.06),0 8px 22px rgba(14,26,51,.08);
  --sh2:0 2px 4px rgba(14,26,51,.08),0 22px 46px rgba(14,26,51,.18);
  --ease:cubic-bezier(.2,.7,.2,1);--spring:cubic-bezier(.34,1.56,.64,1);
  --f-d:'Baloo 2','Nunito',system-ui,sans-serif;--f-b:'Nunito',system-ui,-apple-system,'Segoe UI',sans-serif;--f-s:'Caveat','Segoe Script',cursive;
}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){
  --bg:#09111f;--fg:#e8eefb;--muted:#9aaac6;--card:#101c36;--line:#1d2e52;--soft:#0d1830;--bar:#070d1a;
  --sh1:0 1px 2px rgba(0,0,0,.4),0 8px 22px rgba(0,0,0,.3);--sh2:0 2px 4px rgba(0,0,0,.4),0 22px 46px rgba(0,0,0,.55);color-scheme:dark}}
:root[data-theme="dark"]{
  --bg:#09111f;--fg:#e8eefb;--muted:#9aaac6;--card:#101c36;--line:#1d2e52;--soft:#0d1830;--bar:#070d1a;
  --sh1:0 1px 2px rgba(0,0,0,.4),0 8px 22px rgba(0,0,0,.3);--sh2:0 2px 4px rgba(0,0,0,.4),0 22px 46px rgba(0,0,0,.55);color-scheme:dark}

*{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:84px}
body{margin:0;background:var(--bg);color:var(--fg);font-family:var(--f-b);font-size:16px;line-height:1.6;-webkit-font-smoothing:antialiased;overflow-x:hidden}
.sr{position:absolute;left:-9999px}
a{color:inherit;text-decoration:none}
img{display:block;max-width:100%}
button{font:inherit;color:inherit}
:focus-visible{outline:3px solid var(--sun);outline-offset:3px;border-radius:6px}
.in-w{width:100%;max-width:1180px;margin:0 auto;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}
h1,h2,h3{font-family:var(--f-d);line-height:1.12;margin:0;text-wrap:balance}

/* ---------- motion primitives ---------- */
@keyframes up{from{opacity:0;transform:translateY(24px)}}
@keyframes pop{0%{transform:scale(.6);opacity:0}70%{transform:scale(1.08)}100%{transform:scale(1);opacity:1}}
@keyframes rip{to{transform:scale(1);opacity:0}}
@keyframes shine{to{left:140%}}
@keyframes bell{0%,62%,100%{transform:rotate(0)}6%{transform:rotate(16deg)}12%{transform:rotate(-14deg)}18%{transform:rotate(11deg)}24%{transform:rotate(-8deg)}30%{transform:rotate(4deg)}36%{transform:rotate(0)}}
@keyframes beat{0%,100%{transform:scale(1)}14%{transform:scale(1.22)}28%{transform:scale(1)}42%{transform:scale(1.14)}70%{transform:scale(1)}}
@keyframes float{50%{transform:translateY(-9px)}}
@keyframes drift{0%{transform:translateY(0) rotate(0);opacity:0}15%{opacity:.9}100%{transform:translateY(-220px) rotate(40deg);opacity:0}}
@keyframes orbit{to{transform:rotate(360deg)}}
@keyframes wipe{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0 0 0 0)}}
@keyframes draw{to{stroke-dashoffset:0}}
@keyframes ring{0%{transform:scale(.9);opacity:.8}100%{transform:scale(1.5);opacity:0}}
@keyframes kb{from{transform:scale(1.04)}to{transform:scale(1.12)}}
@keyframes tgl{from{transform:rotate(-90deg) scale(.4);opacity:0}}
.js .pre{opacity:0;transform:translateY(26px)}
.js .pre.in{opacity:1;transform:none;transition:opacity .8s var(--ease) var(--d,0s),transform .8s var(--ease) var(--d,0s)}
.rip-host{position:relative;overflow:hidden}
.rip{position:absolute;border-radius:50%;background:currentColor;opacity:.25;transform:scale(0);animation:rip .65s ease-out forwards;pointer-events:none}
#prog{position:fixed;left:0;top:env(safe-area-inset-top,0px);height:3px;width:0;z-index:100;background:linear-gradient(90deg,var(--sun),var(--red));box-shadow:0 0 10px rgba(255,210,63,.8)}

/* ---------- buttons ---------- */
.btn{position:relative;overflow:hidden;display:inline-flex;align-items:center;justify-content:center;gap:10px;border:0;cursor:pointer;font-weight:800;border-radius:999px;transform:translate(var(--tx,0),var(--ty,0)) scale(var(--sc,1));transition:transform .25s var(--ease),box-shadow .3s,background .25s,color .25s}
.btn:active{--sc:.95}
.btn::after{content:"";position:absolute;top:0;left:-70%;width:40%;height:100%;background:linear-gradient(105deg,transparent,rgba(255,255,255,.55),transparent);transform:skewX(-20deg);pointer-events:none}
.btn:hover::after{animation:shine .8s ease}
.btn-g{background:#fff;color:#1f2937;padding:12px 22px;font-size:15px;box-shadow:0 2px 8px rgba(0,0,0,.18)}
.btn-g:hover{box-shadow:0 10px 26px rgba(0,0,0,.28)}
.btn-g svg{width:20px;height:20px;flex:0 0 auto;transition:transform .5s var(--spring)}
.btn-g:hover svg{transform:rotate(360deg)}
.btn-lg{padding:17px 36px;font-size:19px}
.btn-lg svg{width:30px;height:30px}
.btn-yt{background:var(--red);color:#fff;padding:12px 24px;font-size:16px;box-shadow:0 8px 20px rgba(229,35,27,.4)}
.btn-yt:hover{background:var(--red-d);box-shadow:0 14px 30px rgba(229,35,27,.5)}
.btn-yt .bell{width:20px;height:20px;fill:currentColor;transform-origin:50% 8%;animation:bell 4s ease-in-out infinite}
.btn-ghost{border:1.5px solid var(--line);background:transparent;color:var(--blue);padding:8px 16px;font-size:14px}
.btn-ghost:hover{background:var(--blue);border-color:var(--blue);color:#fff}
.btn-ghost .arr{display:inline-block;transition:transform .35s var(--spring)}
.btn-ghost:hover .arr{transform:translateX(5px)}

/* ---------- header ---------- */
.bar{position:sticky;top:env(safe-area-inset-top,0px);z-index:80;background:var(--bar);color:var(--bar-fg);transition:background .3s,box-shadow .3s}
.bar.stuck{background:color-mix(in srgb,var(--bar) 86%,transparent);-webkit-backdrop-filter:saturate(1.5) blur(14px);backdrop-filter:saturate(1.5) blur(14px);box-shadow:0 12px 30px rgba(3,8,20,.35)}
.bar-in{display:flex;align-items:center;gap:20px;min-height:66px}
.brand{display:flex;align-items:center;gap:12px;font-family:var(--f-d);font-weight:800;font-size:26px;letter-spacing:-.01em;color:#fff}
.yt-mark{width:50px;height:36px;border-radius:10px;background:var(--red);display:grid;place-items:center;flex:0 0 auto;transition:transform .4s var(--spring),box-shadow .3s}
.yt-mark svg{width:20px;height:20px;fill:#fff}
.brand:hover .yt-mark{transform:rotate(-8deg) scale(1.1);box-shadow:0 6px 18px rgba(229,35,27,.55)}
.nav{position:relative;display:flex;gap:6px;margin:0 auto}
.nav a{position:relative;padding:10px 16px;font-weight:700;font-size:15px;color:#c7d4ee;transition:color .25s}
.nav a:hover,.nav a.on{color:#fff}
.nav-ind{position:absolute;left:0;bottom:2px;height:3px;border-radius:3px;background:var(--red);width:0;transition:transform .5s var(--spring),width .5s var(--spring)}
.bar-r{display:flex;align-items:center;gap:10px}
.ic{width:42px;height:42px;border-radius:50%;border:0;background:rgba(255,255,255,.08);color:#fff;display:grid;place-items:center;cursor:pointer;transition:background .25s,transform .3s var(--spring)}
.ic:hover{background:rgba(255,255,255,.18);transform:scale(1.1)}
.ic svg{width:20px;height:20px;fill:currentColor}
.ic .sun{display:none}
:root[data-theme="dark"] .ic .sun{display:block;animation:tgl .5s var(--ease)}
:root[data-theme="dark"] .ic .moon{display:none}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .ic .sun{display:block}:root:not([data-theme="light"]) .ic .moon{display:none}}
.burger{display:none}

/* ---------- hero ---------- */
.hero{position:relative;overflow:hidden;isolation:isolate;background:var(--hero);color:#fff}
.hero-img{position:absolute;inset:0 0 0 auto;width:min(66%,900px);z-index:-1;-webkit-mask-image:linear-gradient(90deg,transparent 0,#000 42%);mask-image:linear-gradient(90deg,transparent 0,#000 42%)}
.hero-img img{width:100%;height:100%;object-fit:cover;object-position:62% 40%;transform:translate3d(var(--px,0),var(--py,0),0) scale(1.06);transition:transform .5s var(--ease);animation:kb 18s ease-in-out infinite alternate}
.hero::after{content:"";position:absolute;inset:0;z-index:-1;background:radial-gradient(60% 90% at 0% 50%,rgba(10,24,40,.55),transparent 70%)}
.hero-in{display:grid;grid-template-columns:minmax(0,1fr);padding-block:56px 48px;min-height:370px;align-content:center}
.hero-copy{max-width:520px}
.hero h1{font-size:clamp(34px,5.2vw,58px);font-weight:700;letter-spacing:-.02em}
.hero h1 .w{display:inline-block;overflow:hidden;vertical-align:top;padding-bottom:.12em;margin-bottom:-.12em}
.hero h1 .w>span{display:inline-block;transform:translateY(112%);animation:up2 .9s var(--ease) forwards;animation-delay:calc(var(--i)*.09s + .15s)}
@keyframes up2{to{transform:none}}
.hero h1 .big{display:block;font-size:1.28em;font-weight:800;color:var(--sun);text-shadow:0 4px 24px rgba(255,210,63,.35);line-height:1.02}
.hero p{margin:14px 0 24px;font-size:clamp(17px,2vw,21px);font-weight:600;max-width:430px;color:#eaf2ff;animation:up .8s var(--ease) .7s backwards}
.hero .btn-g{animation:up .8s var(--ease) .85s backwards}
.hero-links{display:flex;flex-wrap:wrap;align-items:center;gap:10px 16px;margin-top:22px;font-weight:700;font-size:15px;animation:up .8s var(--ease) 1s backwards}
.hero-links .yt-s{width:32px;height:23px;border-radius:7px;background:var(--red);display:grid;place-items:center;animation:beat 3s infinite}
.hero-links .yt-s svg{width:12px;height:12px;fill:#fff}
.hero-links i{width:4px;height:4px;border-radius:50%;background:#fff;opacity:.7}
.hero-links a{transition:color .2s,transform .25s var(--spring);display:inline-block}
.hero-links a:hover{color:var(--sun);transform:translateY(-2px)}
.sparks{position:absolute;inset:0;z-index:-1;pointer-events:none;overflow:hidden}
.sparks i{position:absolute;bottom:-20px;font-style:normal;font-size:18px;opacity:0;animation:drift 9s linear infinite;color:var(--sun)}
.sparks i:nth-child(1){left:52%;animation-delay:0s}.sparks i:nth-child(2){left:63%;animation-delay:2.2s;font-size:14px}.sparks i:nth-child(3){left:74%;animation-delay:4.4s}.sparks i:nth-child(4){left:85%;animation-delay:1.1s;font-size:12px}.sparks i:nth-child(5){left:93%;animation-delay:6s}.sparks i:nth-child(6){left:58%;animation-delay:7s;font-size:13px}

/* ---------- why follow ---------- */
.why{padding-block:56px 36px;text-align:center}
.why h2{font-size:clamp(28px,3.4vw,38px);font-weight:800}
.why-sub{max-width:560px;margin:10px auto 0;color:var(--muted);font-size:17px}
.why-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:20px;margin-top:34px;text-align:left}
.why-card{display:flex;gap:16px;align-items:center;padding:18px;border-radius:20px;border:1px solid transparent;background:transparent;transition:transform .35s var(--ease),background .3s,box-shadow .35s,border-color .3s}
.why-card:hover{background:var(--card);border-color:var(--line);box-shadow:var(--sh2);transform:translateY(calc(var(--cy,0px) - 6px))}
.why-ic{position:relative;flex:0 0 auto;width:64px;height:64px;border-radius:50%;display:grid;place-items:center;color:#fff;background:var(--c)}
.why-ic::after{content:"";position:absolute;inset:0;border-radius:50%;border:2px solid var(--c);opacity:0}
.why-card:hover .why-ic::after{animation:ring 1s ease-out infinite}
.why-ic svg{width:32px;height:32px;fill:currentColor;transition:transform .5s var(--spring)}
.why-card:hover .why-ic svg{transform:scale(1.18) rotate(-8deg)}
.why-card:nth-child(2) .why-ic svg{transform-origin:50% 10%}
.why-card:nth-child(2):hover .why-ic svg{animation:bell 1.2s ease-in-out}
.why-card:nth-child(4):hover .why-ic svg{animation:beat 1s ease-in-out infinite;transform:none}
.why-card h3{font-size:19px;font-weight:700}
.why-card p{margin:2px 0 0;color:var(--muted);font-size:15px;line-height:1.45}

/* ---------- channel card ---------- */
.channel{position:relative;overflow:hidden;display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:30px;align-items:center;padding:26px 34px;border-radius:26px;background:var(--soft);border:1px solid var(--line);transition:box-shadow .4s,transform .4s var(--ease)}
.channel:hover{box-shadow:var(--sh2)}
.ch-logo{position:relative;width:146px;height:146px;flex:0 0 auto}
.ch-logo img{width:100%;height:100%;border-radius:50%;object-fit:cover;position:relative;z-index:1;border:4px solid var(--card);transition:transform .6s var(--spring)}
.channel:hover .ch-logo img{transform:scale(1.05) rotate(-4deg)}
.ch-logo::before{content:"";position:absolute;inset:-9px;border-radius:50%;border:2px dashed var(--red);opacity:.55;animation:orbit 18s linear infinite}
.ch-logo::after{content:"";position:absolute;width:12px;height:12px;border-radius:50%;background:var(--sun);top:-4px;left:50%;margin-left:-6px;transform-origin:6px 81px;animation:orbit 6s linear infinite;z-index:2;box-shadow:0 0 14px var(--sun)}
.ch-name{display:flex;align-items:center;gap:10px;font-size:32px;font-weight:800}
.ver{width:24px;height:24px;fill:#7b8798;flex:0 0 auto}
.ch-handle{color:var(--muted);font-weight:600;font-size:15px}
.ch-bio{margin:6px 0 14px;max-width:420px;color:var(--muted);font-size:16px;line-height:1.5}
.ch-row{display:flex;flex-wrap:wrap;align-items:center;gap:12px 20px}
.ch-stat{font-size:15px;color:var(--muted);font-weight:600}
.ch-stat b{color:var(--fg)}
.ch-stat+.ch-stat{padding-left:20px;border-left:1px solid var(--line)}
.thanks{position:relative;width:280px;max-width:100%;text-align:center;font-family:var(--f-s);font-weight:700;font-size:38px;line-height:1.05;color:#14295e;transform:rotate(-7deg)}
:root[data-theme="dark"] .thanks{color:#a9c3ff}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .thanks{color:#a9c3ff}}
.thanks span{display:block;clip-path:inset(0 100% 0 0)}
.thanks.in span{animation:wipe 1.1s var(--ease) forwards}
.thanks.in span+span{animation-delay:.9s}
.thanks svg{display:block;margin:2px auto 0;width:140px;height:26px;overflow:visible}
.thanks svg path{fill:none;stroke:var(--red);stroke-width:2.5;stroke-linecap:round;stroke-dasharray:160;stroke-dashoffset:160}
.thanks.in svg path{animation:draw .9s ease 1.9s forwards}
.thanks svg .hrt{fill:var(--red);stroke:none;stroke-dasharray:none;transform-box:fill-box;transform-origin:center;animation:beat 1.6s infinite 2.2s}

/* ---------- videos ---------- */
.vids{padding-block:44px 64px}
.sec-h{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:20px}
.sec-h h2{font-size:clamp(26px,3vw,34px);font-weight:800}
.v-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(235px,1fr));gap:22px}
.v-card{display:block;transform:perspective(900px) rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg)) translateY(var(--cy,0px));transition:transform .35s var(--ease)}
.v-card:hover{--cy:-6px}
.v-th{position:relative;aspect-ratio:2.05/1;border-radius:16px;overflow:hidden;background:var(--soft);box-shadow:var(--sh1);transition:box-shadow .4s}
.v-card:hover .v-th{box-shadow:var(--sh2)}
.v-th img{width:100%;height:100%;object-fit:cover;transition:transform .8s var(--ease),filter .4s}
.v-card:hover .v-th img{transform:scale(1.1);filter:saturate(1.15)}
.v-th::before{content:"";position:absolute;inset:0;z-index:1;pointer-events:none;opacity:0;transition:opacity .3s;background:radial-gradient(circle at var(--mx,50%) var(--my,50%),rgba(255,255,255,.28),transparent 55%)}
.v-card:hover .v-th::before{opacity:1}
.v-play{position:absolute;z-index:3;left:50%;top:50%;width:54px;height:54px;margin:-27px 0 0 -27px;border-radius:50%;background:var(--red);display:grid;place-items:center;opacity:0;transform:scale(.5);transition:opacity .3s,transform .45s var(--spring);box-shadow:0 8px 24px rgba(229,35,27,.5)}
.v-play svg{width:22px;height:22px;fill:#fff;margin-left:3px}
.v-card:hover .v-play{opacity:1;transform:none}
.v-dur{position:absolute;z-index:2;right:5px;bottom:4px;min-width:48px;padding:3px 8px;text-align:center;border-radius:6px;background:rgba(10,14,24,.92);color:#fff;font-weight:700;font-size:13px;font-variant-numeric:tabular-nums}
.v-bar{position:absolute;z-index:3;left:0;bottom:0;height:4px;width:0;background:var(--red);transition:width .8s var(--ease)}
.v-card:hover .v-bar{width:100%}
.v-card h3{margin:12px 2px 4px;font-family:var(--f-b);font-weight:800;font-size:16.5px;line-height:1.3}
.v-card h3 span{background:linear-gradient(var(--red),var(--red)) 0 100%/0 2px no-repeat;padding-bottom:2px;transition:background-size .4s var(--ease)}
.v-card:hover h3 span{background-size:100% 2px}
.v-meta{margin:6px 2px 0;color:var(--muted);font-size:13.5px;font-weight:600}

/* ---------- footer ---------- */
.foot{background:var(--bar);color:#c7d4ee;padding-block:34px 26px}
.foot-r{display:flex;flex-wrap:wrap;align-items:center;gap:20px 32px;justify-content:space-between}
.foot .brand{font-size:22px}
.foot .logo-n{width:40px;height:40px;border-radius:50%;object-fit:cover}
.foot-nav{display:flex;flex-wrap:wrap;gap:6px 24px;font-weight:700;font-size:14px}
.foot-nav a{transition:color .2s,transform .25s var(--ease);display:inline-block}
.foot-nav a:hover{color:var(--sun);transform:translateY(-2px)}
.soc{display:flex;align-items:center;gap:10px;font-weight:700;font-size:13px}
.soc a.s{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.07);transition:transform .35s var(--spring),background .25s,color .25s}
.soc a.s:hover{transform:translateY(-5px) rotate(-8deg) scale(1.12);background:var(--red);color:#fff}
.soc svg{width:18px;height:18px;fill:currentColor}
.soc .fu{padding-left:14px;margin-left:4px;border-left:1px solid rgba(255,255,255,.2)}
.copy{margin:22px 0 0;text-align:center;font-size:13.5px;color:#93a6c8}

#top{position:fixed;right:max(16px,env(safe-area-inset-right,0px));bottom:calc(18px + env(safe-area-inset-bottom,0px));z-index:70;width:46px;height:46px;border-radius:50%;border:0;cursor:pointer;color:#111;font-size:20px;font-weight:800;background:conic-gradient(var(--red) calc(var(--p,0)*1%),rgba(0,0,0,.14) 0);box-shadow:var(--sh2);opacity:0;visibility:hidden;transform:translateY(18px) scale(.7);transition:opacity .3s,visibility .3s,transform .4s var(--spring)}
#top::before{content:"";position:absolute;inset:3px;border-radius:50%;background:var(--sun);z-index:-1}
#top.show{opacity:1;visibility:visible;transform:none}
#top.show:hover{transform:translateY(-4px) scale(1.07)}
#toast{position:fixed;left:50%;bottom:calc(26px + env(safe-area-inset-bottom,0px));z-index:120;transform:translateX(-50%);background:#0f172a;color:#fff;font-weight:700;font-size:14px;padding:11px 18px;border-radius:999px;box-shadow:var(--sh2);animation:pop .4s var(--spring)}
canvas#fx{position:fixed;inset:0;width:100%;height:100%;pointer-events:none;z-index:110}

/* ---------- responsive ---------- */
@media (max-width:900px){
  .channel{grid-template-columns:auto minmax(0,1fr);padding:24px}
  .thanks{grid-column:1/-1;justify-self:center;margin-top:6px}
}
@media (max-width:760px){
  .burger{display:grid}
  .nav{position:absolute;left:0;right:0;top:100%;flex-direction:column;gap:0;margin:0;padding:8px max(16px,env(safe-area-inset-left,0px)) 14px;background:var(--bar);display:none;box-shadow:0 18px 30px rgba(3,8,20,.4)}
  .bar.open .nav{display:flex;animation:up .3s var(--ease)}
  .nav-ind{display:none}
  .nav a{padding:12px 4px;border-bottom:1px solid rgba(255,255,255,.07)}
  .brand{font-size:21px;white-space:nowrap;gap:9px}
  .yt-mark{width:42px;height:31px}
  .bar-in{gap:10px}
  .bar-r{margin-left:auto;gap:8px}
  .bar-r .btn-g span{display:none}
  .bar-r .btn-g{padding:10px 12px}
  .hero-img{width:100%;opacity:.5;-webkit-mask-image:none;mask-image:none}
  .hero-in{padding-block:40px 36px}
}
@media (max-width:560px){
  .channel{grid-template-columns:minmax(0,1fr);justify-items:center;text-align:center;gap:18px}
  .ch-name,.ch-row{justify-content:center}
  .ch-stat+.ch-stat{border-left:0;padding-left:0}
  .thanks{font-size:32px}
  .foot-r{justify-content:center;text-align:center}
  .foot-nav,.soc{justify-content:center}
  .btn-lg{padding:15px 26px;font-size:17px}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}
  .hero h1 .w>span{transform:none}.thanks span{clip-path:none}.thanks svg path{stroke-dashoffset:0}
  .js .pre{opacity:1;transform:none}
}

/* ---------- Blogger additions ---------- */
.v-chip{position:absolute;z-index:2;left:8px;top:8px;background:rgba(14,26,51,.78);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);color:#fff;font-size:11px;font-weight:800;letter-spacing:.07em;text-transform:uppercase;padding:4px 10px;border-radius:999px}
.v-ph{position:absolute;inset:0;display:grid;place-items:center;font-size:42px;color:var(--muted);background:var(--soft)}
.sec-t{padding-block:36px 8px}
.arch-t{font-size:clamp(26px,3vw,36px);font-weight:800;margin:0 0 6px}
.arch-s{color:var(--muted);margin:0 0 22px}
.pager{display:flex;justify-content:center;flex-wrap:wrap;gap:12px;margin-top:36px}
.btn-n{background:var(--bar);color:#fff;padding:13px 30px;font-size:15px;box-shadow:var(--sh1)}
.btn-n:hover{background:var(--red);box-shadow:0 12px 26px rgba(229,35,27,.4)}
.btn-n.loading{pointer-events:none;background-image:linear-gradient(45deg,rgba(255,255,255,.18) 25%,transparent 25%,transparent 50%,rgba(255,255,255,.18) 50%,rgba(255,255,255,.18) 75%,transparent 75%);background-size:28px 28px;animation:stripes .8s linear infinite}
@keyframes stripes{to{background-position:28px 0}}
.ad{text-align:center;margin:16px 0}
.main-pad{padding-block:30px 60px}
.post-wrap{max-width:900px}
.crumbs{display:flex;flex-wrap:wrap;gap:8px;font-size:13.5px;font-weight:600;color:var(--muted);margin-bottom:14px}
.crumbs a:hover{color:var(--red)}
.crumbs .cur{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%}
.post-title{font-size:clamp(28px,4.2vw,44px);font-weight:800;letter-spacing:-.02em;margin:0 0 10px}
.post-title .w{display:inline-block;overflow:hidden;vertical-align:top;padding-bottom:.14em;margin-bottom:-.14em}
.post-title .w>span{display:inline-block;transform:translateY(112%);animation:up2 .8s var(--ease) forwards;animation-delay:calc(var(--i)*.06s + .1s)}
@keyframes up2{to{transform:none}}
.meta{display:flex;flex-wrap:wrap;align-items:center;gap:8px 14px;color:var(--muted);font-size:14px;font-weight:600}
.meta .by{display:inline-flex;align-items:center;gap:8px;color:var(--fg)}
.meta .av{width:30px;height:30px;border-radius:50%;background:var(--red);color:#fff;display:grid;place-items:center;font-weight:800;font-size:14px}
.post-body{margin-top:22px;font-size:18px;line-height:1.8;overflow-wrap:anywhere}
.post-body p{margin:0 0 1.1em}
.post-body iframe,.post-body .BLOG_video_class,.post-body object{display:block;width:100%;max-width:100%;aspect-ratio:16/9;height:auto;border:0;border-radius:18px;box-shadow:var(--sh2);background:#000}
.post-body img{border-radius:16px;height:auto}
.post-body a{color:var(--blue);font-weight:700;background:linear-gradient(var(--red),var(--red)) 0 100%/0 2px no-repeat;transition:background-size .35s var(--ease),color .2s}
.post-body a:hover{background-size:100% 2px;color:var(--red)}
.post-body h2,.post-body h3{margin:1.6em 0 .5em}
.post-body blockquote{margin:1.2em 0;padding:14px 22px;border-left:5px solid var(--sun);background:var(--soft);border-radius:0 14px 14px 0;font-style:italic}
.sub-cta{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:16px;margin:30px 0;padding:20px 24px;border-radius:22px;background:var(--soft);border:1px solid var(--line)}
.sub-cta b{font-family:var(--f-d);font-size:21px;display:block}
.sub-cta span{color:var(--muted);font-size:15px}
.tags{display:flex;flex-wrap:wrap;gap:8px;margin:22px 0}
.tag{padding:6px 14px;border-radius:999px;font-weight:800;font-size:12.5px;letter-spacing:.05em;text-transform:uppercase;background:var(--soft);border:1px solid var(--line);color:var(--fg);transition:transform .3s var(--spring),background .25s,color .25s,border-color .25s}
.tag:hover{background:var(--red);border-color:var(--red);color:#fff;transform:translateY(-3px)}
.share{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:18px 0}
.share b{font-size:14px}
.share a{padding:8px 16px;border-radius:999px;font-weight:800;font-size:13px;border:1px solid var(--line);background:var(--card);transition:transform .3s var(--spring),background .25s,color .25s,box-shadow .25s}
.share a:hover{transform:translateY(-3px);box-shadow:var(--sh1);color:#fff}
.share a[data-net='fb']:hover{background:#1877f2}.share a[data-net='x']:hover{background:#111}.share a[data-net='wa']:hover{background:#25d366}.share a[data-net='tg']:hover{background:#229ed9}.share a[data-net='cp']:hover{background:var(--red)}
.share a.ok{background:var(--green);color:#fff;animation:pop .45s var(--spring)}
.post-nav{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:28px 0}
.post-nav a{display:block;padding:14px 18px;border-radius:16px;border:1px solid var(--line);background:var(--card);font-weight:800;transition:transform .3s var(--ease),box-shadow .3s,border-color .3s}
.post-nav a:hover{box-shadow:var(--sh2);border-color:var(--red)}
.post-nav .pv:hover{transform:translateX(-5px)}.post-nav .nx:hover{transform:translateX(5px)}
.post-nav small{display:block;color:var(--muted);font-weight:600}
.post-nav .nx{text-align:right}
.rel h2,.cmts h2{font-size:26px;font-weight:800;margin:34px 0 16px}
.rel .v-grid{grid-template-columns:repeat(auto-fill,minmax(210px,1fr))}
.cmt{padding:14px 0;border-bottom:1px solid var(--line)}
.cmt b{font-weight:800}.cmt small{color:var(--muted);margin-left:8px}
.cmt p{margin:4px 0 0;white-space:pre-line}
.notice{padding:60px 24px;text-align:center;border-radius:24px;background:var(--soft)}
.notice h1{font-size:34px;margin-bottom:10px}
.foot .soc a.s[data-n]{font-size:0}
.ch-stat .stv{font-variant-numeric:tabular-nums}
@media (max-width:560px){.post-nav{grid-template-columns:1fr}.sub-cta{justify-content:center;text-align:center}}

body.script:
//
(function(){

  var doc=document.documentElement,B=document.body;
  var RM=window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches;
  var FINE=window.matchMedia&&matchMedia('(hover:hover) and (pointer:fine)').matches;
  function $(s,c){return (c||document).querySelector(s)}
  function $$(s,c){return Array.prototype.slice.call((c||document).querySelectorAll(s))}
  function esc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}

  /* ---- editable content: swap titles, numbers and images here ---- */
  var CHANNEL='https://www.youtube.com/@NaraMedia';
  var yr=$('#yr');if(yr){yr.textContent=new Date().getFullYear()}

  /* ---- theme ---- */
  var tb=$('#theme');
  tb.addEventListener('click',function(){
    var dark=doc.getAttribute('data-theme')==='dark'||(!doc.getAttribute('data-theme')&&matchMedia('(prefers-color-scheme:dark)').matches);
    doc.setAttribute('data-theme',dark?'light':'dark');
    try{localStorage.setItem('nara-theme',dark?'light':'dark')}catch(e){}
  });
  try{var st=localStorage.getItem('nara-theme');if(st){doc.setAttribute('data-theme',st)}}catch(e){}

  /* ---- mobile menu ---- */
  var bar=$('#bar'),bg=$('#burger');
  bg.addEventListener('click',function(){var o=bar.classList.toggle('open');bg.setAttribute('aria-expanded',o)});
  $$('#nav a').forEach(function(a){a.addEventListener('click',function(){bar.classList.remove('open');bg.setAttribute('aria-expanded','false')})});

  /* ---- scroll: progress, header glass, back to top, spy ---- */
  var prog=$('#prog'),top=$('#top'),links=$$('#nav a'),ind=$('#ind'),secs=['home','about','videos','community'].map(function(id){return document.getElementById(id)}),isHome=!!document.getElementById('home');
  function moveInd(a){
    if(!ind||!a){return}
    var nav=$('#nav'),r=a.getBoundingClientRect(),n=nav.getBoundingClientRect();
    ind.style.width=(r.width-32)+'px';ind.style.transform='translateX('+(r.left-n.left+16)+'px)';
  }
  var cur=0;
  function setOn(i){if(i===cur&&links[i].classList.contains('on')){return}cur=i;links.forEach(function(l,k){l.classList.toggle('on',k===i)});moveInd(links[i])}
  function onScroll(){
    var y=window.pageYOffset||0,max=doc.scrollHeight-window.innerHeight,p=max>0?Math.min(100,y/max*100):0;
    prog.style.width=p+'%';top.style.setProperty('--p',p.toFixed(1));top.classList.toggle('show',y>500);
    bar.classList.toggle('stuck',y>10);
    if(!isHome){return}
    var k=0,line=window.innerHeight*.35;
    secs.forEach(function(s,i){if(s&&s.getBoundingClientRect().top<line){k=i}});
    if(max-y<60){k=3}
    setOn(k);
  }
  window.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('resize',function(){moveInd(links[cur])});
  top.addEventListener('click',function(){window.scrollTo({top:0,behavior:RM?'auto':'smooth'})});
  setTimeout(function(){if(!isHome){if(ind){ind.style.display='none'}onScroll();return}moveInd(links[0]);onScroll()},60);
  if(document.fonts&&document.fonts.ready){document.fonts.ready.then(function(){moveInd(links[cur])})}

  /* ---- reveal (only below-the-fold items start hidden) ---- */
  doc.classList.add('js');
  function show(el){el.classList.add('in');var d=parseFloat(el.style.getPropertyValue('--d'))||0;setTimeout(function(){el.classList.remove('pre');el.classList.remove('in')},(.9+d)*1000+150)}
  var io=('IntersectionObserver' in window)?new IntersectionObserver(function(es){
    es.forEach(function(e){if(e.isIntersecting){show(e.target);io.unobserve(e.target)}});
  },{threshold:.12,rootMargin:'0px 0px -30px 0px'}):null;
  function watch(){
    $$('.pre:not([data-w])').forEach(function(el){
      el.setAttribute('data-w','1');
      var r=el.getBoundingClientRect();
      if(RM||!io||r.top<window.innerHeight*.9){show(el);return}
      io.observe(el);
    });
  }
  watch();
  if('MutationObserver' in window){var wp=0;new MutationObserver(function(){if(!wp){wp=requestAnimationFrame(function(){wp=0;watch()})}}).observe(document.body,{childList:true,subtree:true})}
  var th=$('#thanks');
  if(th){
    var tio=('IntersectionObserver' in window)?new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){th.classList.add('in');tio.disconnect()}})},{threshold:.5}):null;
    if(tio&&!RM){tio.observe(th)}else{th.classList.add('in')}
  }

  /* ---- count-ups ---- */
  function count(el){
    var to=parseFloat(el.getAttribute('data-count')),suf=el.getAttribute('data-suffix')||'';
    if(RM){el.textContent=to+suf;return}
    var t0=null,d=1500;
    function f(t){if(t0===null){t0=t}var p=Math.min(1,(t-t0)/d),e=1-Math.pow(1-p,4);el.textContent=Math.round(to*e)+(p<1?'':suf);if(p<1){requestAnimationFrame(f)}}
    requestAnimationFrame(f);
  }
  if('IntersectionObserver' in window&&!RM){
    var cio=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){count(e.target);cio.unobserve(e.target)}})},{threshold:.6});
    $$('[data-count]').forEach(function(el){cio.observe(el)});
  }

  /* ---- ripple on every button ---- */
  var RIP='.btn,.ic,.soc a.s,#top';
  if(!RM){
    document.addEventListener('pointerdown',function(e){
      var t=e.target.closest&&e.target.closest(RIP);if(!t){return}
      if(getComputedStyle(t).position==='static'){t.style.position='relative'}
      t.classList.add('rip-host');
      var r=t.getBoundingClientRect(),d=Math.max(r.width,r.height)*2,s=document.createElement('span');
      s.className='rip';s.style.cssText='width:'+d+'px;height:'+d+'px;left:'+(e.clientX-r.left-d/2)+'px;top:'+(e.clientY-r.top-d/2)+'px';
      t.appendChild(s);setTimeout(function(){if(s.parentNode){s.parentNode.removeChild(s)}},700);
    },{passive:true});
  }

  /* ---- magnetic buttons + card tilt + hero parallax (mouse only) ---- */
  if(FINE&&!RM){
    var mag=null,tc=null,raf=0,hi=$('#heroImg img');
    document.addEventListener('pointermove',function(e){
      if(e.pointerType!=='mouse'){return}
      var t=e.target.closest?e.target.closest('.btn'):null;
      if(mag&&mag!==t){mag.style.removeProperty('--tx');mag.style.removeProperty('--ty')}
      mag=t;
      if(t){var r=t.getBoundingClientRect();t.style.setProperty('--tx',((e.clientX-r.left-r.width/2)*.16).toFixed(1)+'px');t.style.setProperty('--ty',((e.clientY-r.top-r.height/2)*.24).toFixed(1)+'px')}
      var c=e.target.closest?e.target.closest('.v-card'):null;
      if(tc&&tc!==c){tc.style.removeProperty('--rx');tc.style.removeProperty('--ry')}
      tc=c;
      var x=e.clientX,y=e.clientY;
      if(raf){return}
      raf=requestAnimationFrame(function(){
        raf=0;
        if(tc){var r=tc.getBoundingClientRect(),px=(x-r.left)/r.width,py=(y-r.top)/r.height;
          tc.style.setProperty('--rx',((.5-py)*6).toFixed(2)+'deg');tc.style.setProperty('--ry',((px-.5)*8).toFixed(2)+'deg');
          var th=$('.v-th',tc);th.style.setProperty('--mx',(px*100)+'%');th.style.setProperty('--my',(py*100)+'%')}
        if(hi&&window.pageYOffset<window.innerHeight){hi.style.setProperty('--px',((x/window.innerWidth-.5)*-18).toFixed(1)+'px');hi.style.setProperty('--py',((y/window.innerHeight-.5)*-12).toFixed(1)+'px')}
      });
    },{passive:true});
  }

  /* ---- confetti burst on Subscribe / Sign in ---- */
  var cv=$('#fx'),cx=cv.getContext&&cv.getContext('2d'),parts=[],run=false;
  function size(){cv.width=window.innerWidth*(window.devicePixelRatio||1);cv.height=window.innerHeight*(window.devicePixelRatio||1)}
  size();window.addEventListener('resize',size);
  function burst(x,y){
    if(RM||!cx){return}
    var dpr=window.devicePixelRatio||1,cols=['#e5231b','#ffd23f','#2f7df6','#1fb15a','#9b3fe0','#ffffff'];
    for(var i=0;i<46;i++){var a=Math.random()*Math.PI*2,s=3+Math.random()*7;
      parts.push({x:x*dpr,y:y*dpr,vx:Math.cos(a)*s*dpr,vy:(Math.sin(a)*s-4)*dpr,g:.28*dpr,r:(3+Math.random()*4)*dpr,c:cols[i%cols.length],l:1,rot:Math.random()*6,vr:(Math.random()-.5)*.4})}
    if(!run){run=true;requestAnimationFrame(tick)}
  }
  function tick(){
    cx.clearRect(0,0,cv.width,cv.height);
    parts=parts.filter(function(p){return p.l>0});
    parts.forEach(function(p){p.vy+=p.g;p.x+=p.vx;p.y+=p.vy;p.vx*=.985;p.l-=.014;p.rot+=p.vr;
      cx.save();cx.globalAlpha=Math.max(0,p.l);cx.translate(p.x,p.y);cx.rotate(p.rot);cx.fillStyle=p.c;cx.fillRect(-p.r,-p.r/2,p.r*2,p.r);cx.restore()});
    if(parts.length){requestAnimationFrame(tick)}else{run=false;cx.clearRect(0,0,cv.width,cv.height)}
  }
  function toast(m){var t=$('#toast');if(t){t.remove()}t=document.createElement('div');t.id='toast';t.setAttribute('role','status');t.textContent=m;B.appendChild(t);setTimeout(function(){if(t.parentNode){t.remove()}},2600)}
  $$('[data-burst],[data-cta]').forEach(function(a){a.addEventListener('click',function(e){
    var r=a.getBoundingClientRect();burst(e.clientX||r.left+r.width/2,e.clientY||r.top+r.height/2);
    toast('Opening Nara Media on YouTube...');
  })});

  /* ================= Blogger: thumbnails, feeds, post page ================= */
  var PLAY='<span class="v-play"><svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg></span>';
  function big(u,w,h){
    if(!u){return ''}
    if(/ytimg\.com|youtube\.com\/vi\//.test(u)){return u.replace(/\/(default|mqdefault|sddefault|hqdefault)\.jpg/,'/hqdefault.jpg')}
    return u.replace(/\/(?:s\d+|w\d+-h\d+)[-\w]*\//,'/w'+w+'-h'+h+'-p-k-no-nu/');
  }
  function fixThumbs(root){$$('img.js-thumb',root).forEach(function(i){i.src=big(i.getAttribute('src'),560,272);i.classList.remove('js-thumb')})}
  fixThumbs();
  function fdate(s){try{return new Date(s).toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'})}catch(e){return ''}}
  function parseE(e){
    var link='';(e.link||[]).forEach(function(l){if(l.rel==='alternate'){link=l.href}});
    return {title:e.title.$t,url:link,img:e['media$thumbnail']?e['media$thumbnail'].url:'',date:e.published.$t,cat:(e.category&&e.category[0])?e.category[0].term:''};
  }
  function feed(label,max,cb){
    var u='/feeds/posts/default'+(label?'/-/'+encodeURIComponent(label):'')+'?alt=json&max-results='+max;
    fetch(u).then(function(r){return r.json()}).then(function(d){cb(((d.feed&&d.feed.entry)||[]).map(parseE))}).catch(function(){cb([])});
  }
  function card(p,i){
    return '<a class="v-card pre" style="--d:'+((i||0)*.08)+'s" href="'+esc(p.url)+'"><div class="v-th">'+
      (p.img?'<img alt="'+esc(p.title)+'" loading="lazy" src="'+esc(big(p.img,560,272))+'"/>':'<span class="v-ph">▶</span>')+PLAY+'<i class="v-bar"></i>'+
      (p.cat?'<span class="v-chip">'+esc(p.cat)+'</span>':'')+'</div><h3><span>'+esc(p.title)+'</span></h3><div class="v-meta">Nara Media &nbsp;•&nbsp; '+fdate(p.date)+'</div></a>';
  }

  /* live video count in the channel card */
  var sv=$('#stVids');
  if(sv){
    fetch('/feeds/posts/summary?alt=json&max-results=0').then(function(r){return r.json()}).then(function(d){
      var n=d&&d.feed&&d.feed['openSearch$totalResults']&&d.feed['openSearch$totalResults'].$t;
      if(n){sv.setAttribute('data-count',n);count(sv)}else{sv.parentNode.style.display='none'}
    }).catch(function(){sv.parentNode.style.display='none'});
  }

  /* footer social icons */
  var ICONS={
    youtube:'M21.6 7.2a2.5 2.5 0 0 0-1.8-1.8C18.2 5 12 5 12 5s-6.2 0-7.8.4A2.5 2.5 0 0 0 2.4 7.2C2 8.8 2 12 2 12s0 3.2.4 4.8a2.5 2.5 0 0 0 1.8 1.8C5.8 19 12 19 12 19s6.2 0 7.8-.4a2.5 2.5 0 0 0 1.8-1.8C22 15.2 22 12 22 12s0-3.2-.4-4.8zM10 15V9l5.2 3z',
    instagram:'M7.5 2h9A5.5 5.5 0 0 1 22 7.5v9a5.5 5.5 0 0 1-5.5 5.5h-9A5.5 5.5 0 0 1 2 16.5v-9A5.5 5.5 0 0 1 7.5 2zm0 2A3.5 3.5 0 0 0 4 7.5v9A3.5 3.5 0 0 0 7.5 20h9a3.5 3.5 0 0 0 3.5-3.5v-9A3.5 3.5 0 0 0 16.5 4zM12 7a5 5 0 1 1 0 10 5 5 0 0 1 0-10zm0 2a3 3 0 1 0 0 6 3 3 0 0 0 0-6zm5.3-3.3a1.2 1.2 0 1 1 0 2.4 1.2 1.2 0 0 1 0-2.4z',
    facebook:'M14 8.5V6.8c0-.8.2-1.3 1.4-1.3H17V2.6C16.7 2.5 15.8 2.4 14.7 2.4c-2.4 0-4 1.5-4 4v2.1H8v3.2h2.7v9.9H14v-9.9h2.5l.4-3.2z',
    tiktok:'M16.6 5.8A4.3 4.3 0 0 1 15.5 3h-3.1v12.4a2.6 2.6 0 1 1-1.8-2.5V9.7a5.7 5.7 0 1 0 4.9 5.7V9a7.3 7.3 0 0 0 4.3 1.4V7.3a4.3 4.3 0 0 1-3.2-1.5z',
    x:'M17.8 3h3.1l-6.8 7.7L22 21h-6.2l-4.9-6.400L5.300 21H2.200l7.300-8.300L2 3h6.400l4.400 5.800zm-1.100 16.200h1.700L7.400 4.700H5.600z',
    rss:'M19.2 24C19.2 13.5 10.5 4.8 0 4.8V0c13.200 0 24 10.800 24 24zM3.3 17.400c1.800 0 3.300 1.500 3.300 3.300S5.100 24 3.300 24 0 22.500 0 20.700s1.500-3.300 3.300-3.300zM15.900 24h-4.700C11.200 17.800 6.200 12.800 0 12.800V8.100c8.700 0 15.900 7.200 15.900 15.900z'
  };
  $$('.soc a.s[data-n]').forEach(function(a){
    var n=(a.getAttribute('data-n')||'').toLowerCase().replace(/[^a-z]/g,'');if(n==='twitter'){n='x'}
    var p=ICONS[n];
    a.insertAdjacentHTML('afterbegin',p?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+p+'"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/></svg>');
  });

  /* Load More */
  var more=$('#loadMore'),pgrid=$('#postGrid');
  if(more&&pgrid){
    more.addEventListener('click',function(e){
      e.preventDefault();
      var txt=more.textContent;more.textContent='Loading...';more.classList.add('loading');
      fetch(more.getAttribute('href')).then(function(r){return r.text()}).then(function(t){
        var doc2=new DOMParser().parseFromString(t,'text/html'),g=doc2.querySelector('#postGrid');
        if(g){$$('.v-card',g).forEach(function(c){c.removeAttribute('data-w');pgrid.appendChild(document.importNode(c,true))})}
        fixThumbs(pgrid);
        var nm=doc2.querySelector('#loadMore');
        if(nm){more.setAttribute('href',nm.getAttribute('href'));more.textContent=txt;more.classList.remove('loading')}
        else{more.parentNode.removeChild(more)}
      }).catch(function(){window.location=more.getAttribute('href')});
    });
  }

  /* Post page */
  var pb=$('#postBody');
  if(pb&&B.classList.contains('page-item')){
    var h1=$('h1.post-title');
    if(h1&&!RM){
      var tt=h1.textContent.trim();h1.setAttribute('aria-label',tt);
      h1.innerHTML=tt.split(/\s+/).map(function(w,i){return '<span class="w" aria-hidden="true"><span style="--i:'+i+'">'+esc(w)+'</span></span>'}).join(' ');
    }
    var av=$('.meta .av');if(av){av.textContent=(av.getAttribute('data-name')||'N').trim().charAt(0).toUpperCase()}
    var sh=$('#share');
    if(sh){
      var u=encodeURIComponent(location.href),t=encodeURIComponent(document.title);
      var map={fb:'https://www.facebook.com/sharer/sharer.php?u='+u,x:'https://twitter.com/intent/tweet?url='+u+'&text='+t,wa:'https://wa.me/?text='+t+'%20'+u,tg:'https://t.me/share/url?url='+u+'&text='+t};
      $$('a',sh).forEach(function(a){
        var n=a.getAttribute('data-net');
        if(map[n]){a.href=map[n]}
        else{a.addEventListener('click',function(e){e.preventDefault();
          function ok(){var o=a.getAttribute('data-t')||a.textContent;a.setAttribute('data-t',o);a.textContent='✓ Copied';a.classList.add('ok');toast('Link copied');setTimeout(function(){a.textContent=o;a.classList.remove('ok')},1800)}
          if(navigator.clipboard){navigator.clipboard.writeText(location.href).then(ok,function(){toast('Press Ctrl+C to copy the link')})}
        })}
      });
    }
    var rel=$('#related'),first=$('.tags a');
    if(rel&&first){
      feed(first.textContent.trim(),7,function(a){
        var cur2=location.href.split('?')[0].split('#')[0];
        a=a.filter(function(p){return p.url!==cur2}).slice(0,4);
        if(a.length){rel.innerHTML='<h2>More videos</h2><div class="v-grid">'+a.map(card).join('')+'</div>'}
      });
    }
    var cm=$('#comments');
    if(cm){
      var id=cm.getAttribute('data-post'),list=$('#comment-list');
      fetch('/feeds/'+id+'/comments/default?alt=json&max-results=100').then(function(r){return r.json()}).then(function(d){
        var es=(d.feed&&d.feed.entry)||[];
        if(!es.length){list.innerHTML='<p class="v-meta">No comments yet. Be the first to comment.</p>';return}
        list.innerHTML=es.map(function(e){
          var txt=((e.content&&e.content.$t)||'').replace(/<br\s*\/?>/gi,'\n').replace(/<[^>]*>/g,'');
          var nm=(e.author&&e.author[0]&&e.author[0].name&&e.author[0].name.$t)||'Anonymous';
          return '<div class="cmt"><b>'+esc(nm)+'</b><small>'+fdate(e.published.$t)+'</small><p>'+esc(txt)+'</p></div>';
        }).join('');
      }).catch(function(){list.innerHTML=''});
    }
  }

  /* hide empty ad slots */
  $$('.ad').forEach(function(a){if(!a.querySelector('.widget')){a.style.display='none'}});

})();
